examples.template:
MonarchButton({{trigger}}, variant: .danger) {
    phrase = ""
    isConfirming = true
}
.accessibilityLabel("Revoke \(keyName)")
.sheet(isPresented: $isConfirming) {
    ScrollView {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            MonarchIcon(systemName: "exclamationmark.triangle")
                .foregroundStyle(theme.colors.dangerStrong)
                .frame(width: 40, height: 40)
                .background(Circle().fill(theme.colors.dangerSubtle))
                .accessibilityHidden(true)
            Text("Revoke API key?")
                .monarchTextStyle(.heading)
                .accessibilityAddTraits(.isHeader)
            Text("A revoked key cannot be restored. Create a new key if you still need access.")
                .monarchTextStyle(.body)
                .foregroundStyle(theme.colors.textMuted)
            MonarchCard {
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    Text(keyName).monarchTextStyle(.bodyStrong)
                    Text(keyPrefix)
                        .monarchTextStyle(.caption)
                        .foregroundStyle(theme.colors.textMuted)
                    Text("Last used \(lastUsed.formatted(.relative(presentation: .named)))")
                        .monarchTextStyle(.caption)
                        .foregroundStyle(theme.colors.textMuted)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
            }
            .accessibilityElement(children: .combine)
            MonarchConsequenceList(
                [MonarchConsequence(.removed, "Apps and scripts using this key stop working immediately")],
                heading: "What happens"
            )
            MonarchTypeToConfirmInput(phrase: keyName, text: $phrase)
            if let failure {
                MonarchInlineNotice(failure, tone: .danger)
            }
            HStack(spacing: theme.spacing.space2) {
                Spacer(minLength: 0)
                MonarchButton("Cancel", variant: .secondary) { isConfirming = false }
                    .disabled(isRevoking)
                MonarchButton("Revoke key", variant: .danger, isLoading: isRevoking) {
                    isSteppingUp = true
                }
                .disabled(phrase != keyName)
            }
        }
        .padding(theme.spacing.space6)
    }
    .interactiveDismissDisabled(isRevoking)
    .sheet(isPresented: $isSteppingUp) {
        MonarchStepUpAuthDialog(
            description: "Revoking access needs you to confirm it’s you.",
            onVerified: revoke,
            onVerify: { credential in
                // Send the credential to the server; throw if it is refused.
                try await Task.sleep(for: .milliseconds(300))
            }
        )
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isConfirming = false
@State private var isSteppingUp = false
@State private var phrase = ""
@State private var isRevoking = false
@State private var failure: String?
private let keyName = {{item.label}}
private let keyPrefix = {{item.detail}}
private let lastUsed = Date().addingTimeInterval(-{{item.lastUsedHoursAgo|double}} * 3_600)

private func revoke() {
    isRevoking = true
    failure = nil
    Task {
        do {
            // The app revokes the key on the server here.
            try await Task.sleep(for: .milliseconds(300))
            isRevoking = false
            isConfirming = false
        } catch {
            isRevoking = false
            failure = "Couldn’t revoke the key. Try again."
        }
    }
}

